<template>
  <section><div class="page-heading"><div><p class="eyebrow">العملاء</p><h1>إدارة العملاء والديون</h1></div><button class="primary" @click="add">إضافة عميل</button></div><div class="panel"><div class="toolbar"><input v-model="q" placeholder="بحث بالاسم أو الهاتف..." /></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>الرصيد المستحق</th><th>الإجراء</th></tr></thead><tbody><tr v-for="c in filtered" :key="c._id"><td>{{ c.name }}</td><td>{{ c.phone }}</td><td>{{ money(c.balance) }}</td><td><button class="outline" @click="remind(c)">واتساب</button></td></tr></tbody></table><p v-if="!filtered.length" class="empty">لا يوجد عملاء بعد</p></div></div></section>
</template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import db from '../services/pouchdb';const q=ref(''),customers=ref<any[]>([]);const filtered=computed(()=>customers.value.filter(c=>`${c.name} ${c.phone}`.includes(q.value)));const money=(v:number)=>new Intl.NumberFormat('ar-YE',{style:'currency',currency:'YER',maximumFractionDigits:0}).format(v);async function load(){customers.value=await db.list<any>('customer')}async function add(){const name=prompt('اسم العميل');if(!name)return;const phone=prompt('رقم الهاتف')||'';await db.put({_id:`customer:${Date.now()}`,type:'customer',name,phone,balance:0,created_at:new Date().toISOString()});await load()}function remind(c:any){location.href=`https://wa.me/${c.phone}?text=${encodeURIComponent('تذكير من متجر محاسبي بخصوص الرصيد المستحق')}`}onMounted(load)</script>
